// ── ENZYMES ───────────────────────────────────────────────────────────────────────────────────────
// The machine-readable form of the tables above, for the downstream module that publishes the
// interaction matrix JSON. One entry per page that describes an enzyme or transporter.
//
//   kind     'drug' | 'botanical' | 'food' | 'lifestyle'
//   potency  'strong' | 'moderate' | 'weak' | 'variable' | 'unclear'
//            Drug potency classes follow the FDA AUC-ratio definitions (strong: 5-fold or more;
//            moderate: 2-fold to under 5-fold; weak: 1.25-fold to under 2-fold). Botanical, food and
//            lifestyle entries carry the potency the sourced literature actually supports, and
//            'variable' or 'unclear' is used rather than a false precision.
//   nti      narrow therapeutic index or otherwise high-consequence on a small exposure change.
//   mechanismBased  true where the inhibition is mechanism-based / quasi-irreversible, so it outlasts
//            the presence of the inhibitor in blood and recovery follows enzyme resynthesis.

const sub = (name, nti, note, cites) => F({ name, nti: Boolean(nti), note, cites: F(cites) });
const inh = (name, kind, potency, mechanismBased, note, cites) =>
  F({ name, kind, potency, mechanismBased: Boolean(mechanismBased), note, cites: F(cites) });
const ind = (name, kind, potency, note, cites) => F({ name, kind, potency, note, cites: F(cites) });

